mapper.update:
UPDATE t_session_executions
SET state = 'RUNNING',
    current_segment_id = #{segmentId},
    pending_tool_call_id = NULL,
    updated_at = #{updatedAt}
WHERE session_id = #{sessionId}
  AND execution_id = #{executionId}
  AND current_segment_id = #{previousSegmentId}
  AND state = 'CONFIRMING'
  AND pending_tool_call_id = #{toolCallId}
  AND pending_plan_event_id IS NULL
  AND pending_question_event_id IS NULL
  AND stop_event_id IS NULL

UPDATE t_session_executions
SET state = 'RUNNING',
    current_segment_id = #{segmentId},
    pending_tool_call_id = NULL,
    pending_plan_event_id = NULL,
    updated_at = #{updatedAt}
WHERE session_id = #{sessionId}
  AND execution_id = #{executionId}
  AND current_segment_id = #{previousSegmentId}
  AND state = 'CONFIRMING'
  AND pending_tool_call_id = #{toolCallId}
  AND pending_plan_event_id = #{planEventId}
  AND pending_question_event_id IS NULL
  AND stop_event_id IS NULL

UPDATE t_session_executions
SET state = 'RUNNING',
    current_segment_id = #{segmentId},
    pending_tool_call_id = NULL,
    pending_question_event_id = NULL,
    updated_at = #{updatedAt}
WHERE session_id = #{sessionId}
  AND execution_id = #{executionId}
  AND current_segment_id = #{previousSegmentId}
  AND state = 'CONFIRMING'
  AND pending_tool_call_id = #{toolCallId}
  AND pending_plan_event_id IS NULL
  AND pending_question_event_id = #{questionEventId}
  AND stop_event_id IS NULL

UPDATE t_session_tool_confirmations decision
SET state = 'CLAIMED',
    claimed_at = #{claimedAt}
WHERE decision.session_id = #{sessionId}
  AND decision.execution_id = #{executionId}
  AND decision.previous_segment_id = #{previousSegmentId}
  AND decision.tool_call_id = #{toolCallId}
  AND decision.state = 'PENDING'
  AND EXISTS (
      SELECT 1
      FROM t_session_executions execution
      WHERE execution.session_id = decision.session_id
        AND execution.execution_id = decision.execution_id
        AND execution.root_event_id = #{rootEventId}
        AND execution.current_segment_id = decision.segment_id
        AND execution.state = 'RUNNING'
        AND execution.stop_event_id IS NULL
  )

