mapper.update:
UPDATE t_session_question_answers answer
SET state = 'CLAIMED',
    claimed_at = #{claimedAt}
WHERE answer.session_id = #{sessionId}
  AND answer.execution_id = #{executionId}
  AND answer.previous_segment_id = #{previousSegmentId}
  AND answer.target_event_id = #{questionEventId}
  AND answer.state = 'PENDING'
  AND EXISTS (
      SELECT 1
      FROM t_session_executions execution
      WHERE execution.session_id = answer.session_id
        AND execution.execution_id = answer.execution_id
        AND execution.root_event_id = #{rootEventId}
        AND execution.current_segment_id = answer.segment_id
        AND execution.state = 'RUNNING'
        AND execution.stop_event_id IS NULL
  )

mapper.select:
SELECT answer.session_id, answer.execution_id, answer.answer_event_id,
       answer.target_event_id, answer.previous_segment_id, answer.segment_id,
       answer.tool_call_id, answer.state, answer.created_at, answer.claimed_at,
       answer.completed_at, event.payload::text AS answer_payload
FROM t_session_question_answers answer
JOIN t_session_events event
  ON event.session_id = answer.session_id
 AND event.event_id = answer.answer_event_id
WHERE answer.session_id = #{sessionId}
  AND answer.execution_id = #{executionId}
  AND answer.previous_segment_id = #{previousSegmentId}
  AND answer.target_event_id = #{questionEventId}
  AND answer.state = 'CLAIMED'

