  AND execution_id = #{executionId}
  AND answer_event_id = #{answerEventId}
  AND state = 'CLAIMED'

mapper.select:
WITH targets (session_id, execution_id, root_event_id, segment_id) AS (
SELECT CAST(#{target.sessionId} AS VARCHAR(128)), CAST(#{target.executionId} AS VARCHAR(128)), CAST(#{target.rootEventId} AS VARCHAR(128)), CAST(#{target.segmentId} AS VARCHAR(128))
) SELECT target.session_id, target.execution_id, target.root_event_id, CASE WHEN execution.stop_event_id IS NULL THEN target.segment_id ELSE execution.current_segment_id END AS segment_id, CASE WHEN execution.stop_event_id IS NULL THEN FALSE ELSE TRUE END AS stop_requested, confirmation.tool_call_id, plan_confirmation.target_event_id AS plan_event_id, question_answer.target_event_id AS question_event_id FROM targets target JOIN LATERAL ( SELECT current_segment_id, stop_event_id FROM t_session_executions WHERE session_id = target.session_id AND execution_id = target.execution_id AND root_event_id = target.root_event_id AND state <> 'TERMINAL' LIMIT 1 ) execution ON TRUE LEFT JOIN LATERAL ( SELECT confirmation_event_id, tool_call_id FROM t_session_tool_confirmations WHERE session_id = target.session_id AND execution_id = target.execution_id AND previous_segment_id = target.segment_id AND segment_id = execution.current_segment_id AND state = 'PENDING' LIMIT 1 ) confirmation ON TRUE LEFT JOIN LATERAL ( SELECT confirmation_event_id, target_event_id FROM t_session_plan_confirmations WHERE session_id = target.session_id AND execution_id = target.execution_id AND previous_segment_id = target.segment_id AND segment_id = execution.current_segment_id AND state = 'PENDING' LIMIT 1 ) plan_confirmation ON TRUE LEFT JOIN LATERAL ( SELECT answer_event_id, target_event_id FROM t_session_question_answers WHERE session_id = target.session_id AND execution_id = target.execution_id AND previous_segment_id = target.segment_id AND segment_id = execution.current_segment_id AND state = 'PENDING' LIMIT 1 ) question_answer ON TRUE WHERE execution.stop_event_id IS NOT NULL OR confirmation.confirmation_event_id IS NOT NULL OR plan_confirmation.confirmation_event_id IS NOT NULL OR question_answer.answer_event_id IS NOT NULL ORDER BY target.session_id, target.execution_id

mapper.update:
UPDATE t_session_tool_confirmations
SET state = 'CANCELED',
    completed_at = #{completedAt}
WHERE session_id = #{sessionId}
  AND execution_id = #{executionId}
  AND state = 'PENDING'

UPDATE t_session_plan_confirmations
SET state = 'CANCELED',
    completed_at = #{completedAt}
WHERE session_id = #{sessionId}
  AND execution_id = #{executionId}
  AND state = 'PENDING'

UPDATE t_session_question_answers
SET state = 'CANCELED',
    completed_at = #{completedAt}
WHERE session_id = #{sessionId}
  AND execution_id = #{executionId}
  AND state = 'PENDING'

UPDATE t_session_executions
SET state = 'TERMINAL',
    pending_tool_call_id = NULL,
    pending_plan_event_id = NULL,
    pending_question_event_id = NULL,
    terminal_event_id = #{terminalEventId},
    terminal_reason = #{terminalReason},
    updated_at = #{terminalAt},
    terminal_at = #{terminalAt}
WHERE session_id = #{sessionId}
  AND execution_id = #{executionId}
  AND current_segment_id = #{segmentId}
  AND state IN ('RUNNING', 'CONFIRMING', 'STOPPING')
